      "gene_symbol": "EIF2AK1",
      "confidence": 0.75,
      "cited_ids": [],
      "rationale": "EIF2AK1 is an erythroid-specific kinase that senses heme and balances globin synthesis, making it a strong candidate for translational and transcriptional control of fetal hemoglobin."
    },
    {
      "gene_symbol": "HIC2",
      "confidence": 0.7,
      "cited_ids": [],
      "rationale": "HIC2 is a developmental zinc-finger repressor expressed in hematopoietic lineages with potential regulatory involvement in globin gene switching."
    },
    {
      "gene_symbol": "ATF4",
      "confidence": 0.65,
      "cited_ids": [],
      "rationale": "ATF4 is a key transcriptional effector of the integrated stress response downstream of eIF2alpha kinases in erythroid cells, implicating it in globin regulation."
    },
    {
      "gene_symbol": "ZNF410",
      "confidence": 0.6,
